import { Text, View, WebView } from "nsh";
import { pluginPage } from "./page";
import type { PluginChannel } from "./bridge";
import type { InstalledPlugin } from "./types";

/** A plugin, running.
 *
 *  The page is generated by the app (`page.ts`) and lives in a web view that is
 *  never shown: a plugin has no UI of the app's, it answers calls. The web view
 *  still runs its timers and its network while `display: none` (measured: 15
 *  ticks in 4 s at 250 ms, against 14 for a visible one), so a hidden plugin is
 *  not a throttled one. */
export function PluginView(props: { plugin: InstalledPlugin; channel: PluginChannel; onError: (line: string) => void }) {
  return (
    <View style={{ display: "none" }} testID={`plugin-view-${props.plugin.manifest.id}`}>
      <Text>{props.plugin.manifest.name}</Text>
      <WebView
        ref={(node: any) => props.channel.attach(node)}
        html={pluginPage(props.plugin.source)}
        onMessage={(e: any) => props.channel.onPageMessage(String(e?.data ?? ""))}
        onError={(e: any) => props.onError(`插件 ${props.plugin.manifest.id} 页面失败: ${String(e?.message ?? e)}`)}
      />
    </View>
  );
}
